def diag_segment_check(X,Y, color):
 r,c=len(X),len(X[0]); out=[]
 for i in range(r):
  for j in range(c):
   if X[i][j]!=color: continue
   for di,dj in [(1,1),(1,-1)]:
    k=1
    while 0<=i+di*k<r and 0<=j+dj*k<c:
     ii,jj=i+di*k,j+dj*k
     if X[ii][jj]==color:
      for t in range(1,k):
       x,y=i+di*t,j+dj*t
       out.append((x,y,Y[x][y]))
     k+=1
 return out
