def samecomp_gaps(X,m,Y):
 R,C=len(X),len(X[0]); labels=[[-1]*C for _ in range(R)]; k=0
 for r in range(R):
  for c in range(C):
   if X[r][c]==m and labels[r][c]<0:
    q=[(r,c)]; labels[r][c]=k
    for i,j in q:
     for di,dj in [(1,0),(-1,0),(0,1),(0,-1)]:
      ni,nj=i+di,j+dj
      if 0<=ni<R and 0<=nj<C and X[ni][nj]==m and labels[ni][nj]<0:
       labels[ni][nj]=k;q.append((ni,nj))
    k+=1
 bad=[]
 for r in range(R):
  cs=[c for c in range(C) if X[r][c]==m]
  for c1,c2 in zip(cs,cs[1:]):
   if labels[r][c1]==labels[r][c2]:
    bad += [(r,c,Y[r][c]) for c in range(c1+1,c2)]
 for c in range(C):
  rs=[r for r in range(R) if X[r][c]==m]
  for r1,r2 in zip(rs,rs[1:]):
   if labels[r1][c]==labels[r2][c]: bad += [(r,c,Y[r][c]) for r in range(r1+1,r2)]
 return bad
